     9→/**
    10→ * Selector for all focusable elements within a container
    11→ */
    12→const FOCUSABLE_SELECTOR = [
    13→  'button:not([disabled])',
    14→  'a[href]',
    15→  'input:not([disabled])',
    16→  'select:not([disabled])',
    17→  'textarea:not([disabled])',
    18→  '[tabindex]:not([tabindex="-1"])',
    19→].join(', ');
    20→
    21→/**
    22→ * Gets all focusable elements within a container
    23→ */
    24→function getFocusableElements(container: HTMLElement): HTMLElement[] {
    25→  const elements = container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR);
    26→  return Array.from(elements);
    27→}
    28→
    29→/**
    30→ * Custom hook for trapping focus within a container element.
    31→ * Handles Tab/Shift+Tab key navigation to cycle through focusable elements.
    32→ */
    33→function useFocusTrap(containerRef: React.RefObject<HTMLElement | null>, isActive: boolean) {
    34→  useEffect(() => {
    35→    if (!isActive || !containerRef.current) {
    36→      return;
    37→    }
    38→
    39→    const container = containerRef.current;
    40→
    41→    const handleKeyDown = (event: KeyboardEvent) => {
    42→      if (event.key !== 'Tab') {
    43→        return;
    44→      }
    45→
    46→      const focusableElements = getFocusableElements(container);
    47→      if (focusableElements.length === 0) {
    48→        event.preventDefault();
    49→        return;
    50→      }
    51→
    52→      const firstElement = focusableElements[0];
    53→      const lastElement = focusableElements[focusableElements.length - 1];
    54→      const activeElement = document.activeElement;
    55→
    56→      // Shift+Tab from first element goes to last
    57→      if (event.shiftKey && activeElement === firstElement) {
    58→        event.preventDefault();
    59→        lastElement.focus();
    60→      }
    61→      // Tab from last element goes to first
    62→      else if (!event.shiftKey && activeElement === lastElement) {
    63→        event.preventDefault();
    64→        firstElement.focus();
    65→      }
    66→      // If focus is outside the container, move it inside
    67→      else if (!container.contains(activeElement)) {
    68→        event.preventDefault();
    69→        firstElement.focus();
    70→      }
    71→    };
    72→
    73→    document.addEventListener('keydown', handleKeyDown);
    74→    return () => document.removeEventListener('keydown', handleKeyDown);
    75→  }, [containerRef, isActive]);
    76→}
    77→
    78→/**
    79→ * Custom hook to manage focus when a dialog opens and closes.
    80→ * - Stores the previously focused element
    81→ * - Focuses the first focusable element in the container on open
    82→ * - Restores focus to the previous element on close
    83→ */
    84→function useFocusManagement(
    85→  containerRef: React.RefObject<HTMLElement | null>,
    86→  closeButtonRef: React.RefObject<HTMLElement | null>,
    87→  isOpen: boolean
    88→) {
    89→  // Store the element that was focused before the dialog opened
    90→  const previouslyFocusedRef = useRef<HTMLElement | null>(null);
    91→
    92→  useEffect(() => {
    93→    if (isOpen) {
    94→      // Store the currently focused element before dialog opens
    95→      previouslyFocusedRef.current = document.activeElement as HTMLElement;
    96→
    97→      // Focus the close button (or first focusable element) when dialog opens
    98→      // Use requestAnimationFrame to ensure the DOM is fully rendered
    99→      requestAnimationFrame(() => {
   100→        if (closeButtonRef.current) {
   101→          closeButtonRef.current.focus();
   102→        } else if (containerRef.current) {
   103→          const focusableElements = getFocusableElements(containerRef.current);
   104→          if (focusableElements.length > 0) {
   105→            focusableElements[0].focus();
   106→          }
   107→        }
   108→      });
   109→    } else {
   110→      // Restore focus to the previously focused element when dialog closes
   111→      if (previouslyFocusedRef.current && previouslyFocusedRef.current.focus) {
   112→        previouslyFocusedRef.current.focus();
   113→        previouslyFocusedRef.current = null;
   114→      }
   115→    }
   116→  }, [isOpen, containerRef, closeButtonRef]);
   117→}
