   122→function KeyBadge({ keyText }: { keyText: string }) {
   123→  return (
   124→    <span className="inline-flex items-center justify-center min-w-[1.5rem] h-6 px-1.5 mx-0.5 bg-gray-100 border border-gray-300 rounded text-xs font-mono font-medium text-gray-700 shadow-sm">
   125→      {keyText}
   126→    </span>
   127→  );
   128→}
   129→
   130→/**
   131→ * Parses a formatted key string and renders it as visual key badges.
   132→ * Handles both Mac (no separator, uses symbols) and Windows (+ separator) formats.
   133→ */
   134→function ShortcutKeyDisplay({ keys }: { keys: string }) {
   135→  const onMac = isMac();
   136→
   137→  // Mac uses symbols without separator, Windows uses + separator
   138→  const keyParts = useMemo(() => {
   139→    if (onMac) {
   140→      // Mac format: symbols like ⌘⇧Z or single keys like S
   141→      // Split by known modifier symbols while keeping them
   142→      const parts: string[] = [];
   143→      let remaining = keys;
   144→      const modifiers = ['⌘', '⌥', '⇧', '⌃'];
   145→
   146→      for (const mod of modifiers) {
   147→        if (remaining.startsWith(mod)) {
   148→          parts.push(mod);
   149→          remaining = remaining.slice(mod.length);
   150→        }
   151→      }
   152→
   153→      if (remaining) {
   154→        parts.push(remaining);
   155→      }
   156→
   157→      return parts;
   158→    } else {
   159→      // Windows format: Ctrl+Shift+Z
   160→      return keys.split('+').map(k => k.trim());
   161→    }
   162→  }, [keys, onMac]);
   163→
   164→  return (
   165→    <span className="inline-flex items-center">
   166→      {keyParts.map((part, index) => (
   167→        <KeyBadge key={index} keyText={part} />
   168→      ))}
   169→    </span>
   170→  );
   171→}
   172→
   173→/**
   174→ * Renders a single shortcut row with key badge(s) and description
   175→ */
   176→function ShortcutRow({ shortcut }: { shortcut: ShortcutDisplayInfo }) {
   177→  return (
   178→    <div className="flex items-center justify-between py-1.5 px-2 rounded hover:bg-gray-50">
   179→      <span className="text-gray-600 mr-4">{shortcut.description}</span>
   180→      <ShortcutKeyDisplay keys={shortcut.keys} />
   181→    </div>
   182→  );
   183→}
   184→
   185→/**
   186→ * Renders a category section with all its shortcuts
   187→ */
   188→function ShortcutCategorySection({ group }: { group: ShortcutGroup }) {
   189→  if (group.shortcuts.length === 0) {
   190→    return null;
   191→  }
   192→
   193→  return (
   194→    <div className="mb-4 last:mb-0">
   195→      <h4 className="font-medium text-gray-800 mb-2 pb-1 border-b border-gray-200">
   196→        {group.label}
   197→      </h4>
   198→      <div className="space-y-0.5">
   199→        {group.shortcuts.map((shortcut, index) => (
   200→          <ShortcutRow key={`${group.category}-${index}`} shortcut={shortcut} />
   201→        ))}
   202→      </div>
   203→    </div>
   204→  );
   205→}
