   207→/**
   208→ * Main keyboard shortcuts section for the help overlay
   209→ */
   210→function KeyboardShortcutsSection() {
   211→  const groups = useMemo(() => {
   212→    const registry = getGlobalShortcutRegistry();
   213→    return registry.getGroupedShortcuts();
   214→  }, []);
   215→
   216→  const onMac = isMac();
   217→
   218→  if (groups.length === 0) {
   219→    return null;
   220→  }
   221→
   222→  return (
   223→    <section>
   224→      <h3 className="font-semibold text-lg mb-3">Keyboard Shortcuts</h3>
   225→      <div className="text-xs text-gray-500 mb-3">
   226→        {onMac ? 'Using Mac shortcuts (⌘ = Command)' : 'Using Windows/Linux shortcuts'}
   227→      </div>
   228→      <div className="bg-gray-50 rounded-lg p-4">
   229→        {groups.map((group) => (
