     6→export type ShortcutDisabledReason =
     7→  | 'modal_open'
     8→  | 'user_disabled'
     9→  | 'input_focused'
    10→  | null;
    11→
    12→/**
    13→ * State interface for keyboard shortcuts management
    14→ */
    15→interface KeyboardState {
    16→  /** Whether keyboard shortcuts are globally enabled */
    17→  shortcutsEnabled: boolean;
    18→  /** Whether the help overlay is currently visible */
    19→  helpOverlayOpen: boolean;
    20→  /** Reason why shortcuts are currently disabled (null if enabled) */
    21→  disabledReason: ShortcutDisabledReason;
    22→  /** Count of open modals (to handle nested modals) */
    23→  openModalCount: number;
    24→
    25→  // Actions - Enable/Disable shortcuts
    26→  /** Enable all keyboard shortcuts */
    27→  enableShortcuts: () => void;
    28→  /** Disable all keyboard shortcuts */
    29→  disableShortcuts: (reason?: ShortcutDisabledReason) => void;
    30→  /** Toggle shortcuts enabled state */
    31→  toggleShortcuts: () => void;
    32→
    33→  // Actions - Help overlay
    34→  /** Open the help overlay */
    35→  openHelpOverlay: () => void;
    36→  /** Close the help overlay */
    37→  closeHelpOverlay: () => void;
    38→  /** Toggle the help overlay visibility */
    39→  toggleHelpOverlay: () => void;
    40→  /** Set help overlay state directly */
    41→  setHelpOverlayOpen: (isOpen: boolean) => void;
    42→
    43→  // Actions - Modal tracking (for auto-disable)
    44→  /** Register that a modal has been opened */
    45→  registerModalOpen: () => void;
    46→  /** Register that a modal has been closed */
    47→  registerModalClose: () => void;
    48→
    49→  // Derived state helpers
    50→  /** Check if shortcuts are currently active (enabled and no modals) */
    51→  areShortcutsActive: () => boolean;
    52→
    53→  // Reset
    54→  /** Reset keyboard state to defaults */
    55→  reset: () => void;
    56→}
    57→
    58→/**
    59→ * Default state values
    60→ */
    61→const DEFAULT_STATE = {
    62→  shortcutsEnabled: true,
    63→  helpOverlayOpen: false,
    64→  disabledReason: null as ShortcutDisabledReason,
    65→  openModalCount: 0,
    66→};
    67→
    68→/**
    69→ * Zustand store for managing keyboard shortcut state.
    70→ *
    71→ * This store tracks:
    72→ * - Global enabled/disabled state for keyboard shortcuts
    73→ * - Help overlay visibility
    74→ * - Modal dialog count (for auto-disabling shortcuts when modals are open)
    75→ *
    76→ * @example
    77→ * ```tsx
    78→ * function MyComponent() {
    79→ *   const shortcutsEnabled = useKeyboardStore((state) => state.shortcutsEnabled);
    80→ *   const toggleShortcuts = useKeyboardStore((state) => state.toggleShortcuts);
    81→ *
    82→ *   return (
    83→ *     <button onClick={toggleShortcuts}>
    84→ *       Shortcuts: {shortcutsEnabled ? 'On' : 'Off'}
    85→ *     </button>
    86→ *   );
    87→ * }
    88→ * ```
    89→ */
    90→export const useKeyboardStore = create<KeyboardState>((set, get) => ({
    91→  shortcutsEnabled: DEFAULT_STATE.shortcutsEnabled,
    92→  helpOverlayOpen: DEFAULT_STATE.helpOverlayOpen,
    93→  disabledReason: DEFAULT_STATE.disabledReason,
    94→  openModalCount: DEFAULT_STATE.openModalCount,
    95→
    96→  enableShortcuts: () => {
    97→    set({
    98→      shortcutsEnabled: true,
    99→      disabledReason: null,
   100→    });
   101→  },
   102→
   103→  disableShortcuts: (reason: ShortcutDisabledReason = 'user_disabled') => {
   104→    set({
   105→      shortcutsEnabled: false,
   106→      disabledReason: reason,
   107→    });
   108→  },
   109→
   110→  toggleShortcuts: () => {
   111→    const { shortcutsEnabled } = get();
   112→    if (shortcutsEnabled) {
   113→      set({
   114→        shortcutsEnabled: false,
   115→        disabledReason: 'user_disabled',
   116→      });
   117→    } else {
   118→      set({
   119→        shortcutsEnabled: true,
   120→        disabledReason: null,
   121→      });
   122→    }
   123→  },
   124→
   125→  openHelpOverlay: () => {
   126→    set({ helpOverlayOpen: true });
   127→  },
   128→
   129→  closeHelpOverlay: () => {
   130→    set({ helpOverlayOpen: false });
   131→  },
   132→
   133→  toggleHelpOverlay: () => {
   134→    set((state) => ({ helpOverlayOpen: !state.helpOverlayOpen }));
   135→  },
   136→
   137→  setHelpOverlayOpen: (isOpen: boolean) => {
   138→    set({ helpOverlayOpen: isOpen });
   139→  },
   140→
   141→  registerModalOpen: () => {
   142→    const { openModalCount } = get();
   143→    const newCount = openModalCount + 1;
   144→    set({
   145→      openModalCount: newCount,
   146→      // Only set disabledReason if not already disabled for another reason
   147→      disabledReason: get().disabledReason ?? 'modal_open',
   148→    });
   149→  },
   150→
   151→  registerModalClose: () => {
   152→    const { openModalCount, disabledReason } = get();
   153→    const newCount = Math.max(0, openModalCount - 1);
   154→    set({
   155→      openModalCount: newCount,
   156→      // Clear the modal_open reason if all modals are closed
   157→      disabledReason:
   158→        newCount === 0 && disabledReason === 'modal_open'
   159→          ? null
   160→          : disabledReason,
   161→    });
   162→  },
   163→
   164→  areShortcutsActive: () => {
   165→    const { shortcutsEnabled, openModalCount, helpOverlayOpen } = get();
   166→    // Shortcuts are active if:
   167→    // 1. They are globally enabled
   168→    // 2. No modals are open (except help overlay has special handling)
   169→    // Note: Help overlay uses allowInModal for Esc key
   170→    return shortcutsEnabled && openModalCount === 0 && !helpOverlayOpen;
   171→  },
   172→
   173→  reset: () => {
   174→    set({
   175→      shortcutsEnabled: DEFAULT_STATE.shortcutsEnabled,
   176→      helpOverlayOpen: DEFAULT_STATE.helpOverlayOpen,
   177→      disabledReason: DEFAULT_STATE.disabledReason,
   178→      openModalCount: DEFAULT_STATE.openModalCount,
   179→    });
   180→  },
   181→}));
   182→
   183→/**
   184→ * Selector to get shortcuts enabled state
   185→ */
   186→export const selectShortcutsEnabled = (state: KeyboardState): boolean =>
   187→  state.shortcutsEnabled;
   188→
   189→/**
   190→ * Selector to get help overlay open state
   191→ */
   192→export const selectHelpOverlayOpen = (state: KeyboardState): boolean =>
   193→  state.helpOverlayOpen;
   194→
   195→/**
   196→ * Selector to get the reason shortcuts are disabled
   197→ */
   198→export const selectDisabledReason = (
   199→  state: KeyboardState
   200→): ShortcutDisabledReason => state.disabledReason;
   201→
   202→/**
   203→ * Selector to check if shortcuts are currently active
   204→ */
   205→export const selectAreShortcutsActive = (state: KeyboardState): boolean =>
   206→  state.areShortcutsActive();
