    10→/**
    11→ * Selector for all focusable elements within a container
    12→ */
    13→const FOCUSABLE_SELECTOR = [
    14→  'button:not([disabled])',
    15→  'a[href]',
    16→  'input:not([disabled])',
    17→  'select:not([disabled])',
    18→  'textarea:not([disabled])',
    19→  '[tabindex]:not([tabindex="-1"])',
    20→].join(', ');
    21→
    22→/**
    23→ * Gets all focusable elements within a container
    24→ */
    25→function getFocusableElements(container: HTMLElement): HTMLElement[] {
    26→  const elements = container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR);
    27→  return Array.from(elements);
    28→}
    29→
    30→/**
    31→ * Custom hook for trapping focus within a container element.
    32→ * Handles Tab/Shift+Tab key navigation to cycle through focusable elements.
    33→ */
    34→function useFocusTrap(containerRef: React.RefObject<HTMLElement | null>, isActive: boolean) {
    35→  useEffect(() => {
    36→    if (!isActive || !containerRef.current) {
    37→      return;
    38→    }
    39→
    40→    const container = containerRef.current;
    41→
    42→    const handleKeyDown = (event: KeyboardEvent) => {
    43→      if (event.key !== 'Tab') {
    44→        return;
    45→      }
    46→
    47→      const focusableElements = getFocusableElements(container);
    48→      if (focusableElements.length === 0) {
    49→        event.preventDefault();
    50→        return;
    51→      }
    52→
    53→      const firstElement = focusableElements[0];
    54→      const lastElement = focusableElements[focusableElements.length - 1];
    55→      const activeElement = document.activeElement;
    56→
    57→      // Shift+Tab from first element goes to last
    58→      if (event.shiftKey && activeElement === firstElement) {
    59→        event.preventDefault();
    60→        lastElement.focus();
    61→      }
    62→      // Tab from last element goes to first
    63→      else if (!event.shiftKey && activeElement === lastElement) {
    64→        event.preventDefault();
    65→        firstElement.focus();
    66→      }
    67→      // If focus is outside the container, move it inside
    68→      else if (!container.contains(activeElement)) {
    69→        event.preventDefault();
    70→        firstElement.focus();
    71→      }
    72→    };
    73→
    74→    document.addEventListener('keydown', handleKeyDown);
    75→    return () => document.removeEventListener('keydown', handleKeyDown);
    76→  }, [containerRef, isActive]);
    77→}
