    79→/**
    80→ * Custom hook to manage focus when a dialog opens and closes.
    81→ * - Stores the previously focused element
    82→ * - Focuses the first focusable element in the container on open
    83→ * - Restores focus to the previous element on close
    84→ */
    85→function useFocusManagement(
    86→  containerRef: React.RefObject<HTMLElement | null>,
    87→  closeButtonRef: React.RefObject<HTMLElement | null>,
    88→  isOpen: boolean
    89→) {
    90→  // Store the element that was focused before the dialog opened
    91→  const previouslyFocusedRef = useRef<HTMLElement | null>(null);
    92→
    93→  useEffect(() => {
    94→    if (isOpen) {
    95→      // Store the currently focused element before dialog opens
    96→      previouslyFocusedRef.current = document.activeElement as HTMLElement;
    97→
    98→      // Focus the close button (or first focusable element) when dialog opens
    99→      // Use requestAnimationFrame to ensure the DOM is fully rendered
   100→      requestAnimationFrame(() => {
   101→        if (closeButtonRef.current) {
   102→          closeButtonRef.current.focus();
   103→        } else if (containerRef.current) {
   104→          const focusableElements = getFocusableElements(containerRef.current);
   105→          if (focusableElements.length > 0) {
   106→            focusableElements[0].focus();
   107→          }
   108→        }
   109→      });
   110→    } else {
   111→      // Restore focus to the previously focused element when dialog closes
   112→      if (previouslyFocusedRef.current && previouslyFocusedRef.current.focus) {
   113→        previouslyFocusedRef.current.focus();
   114→        previouslyFocusedRef.current = null;
   115→      }
   116→    }
   117→  }, [isOpen, containerRef, closeButtonRef]);
   118→}
