   131→/**
   132→ * Parses a formatted key string and renders it as visual key badges.
   133→ * Handles both Mac (no separator, uses symbols) and Windows (+ separator) formats.
   134→ */
   135→function ShortcutKeyDisplay({ keys }: { keys: string }) {
   136→  const onMac = isMac();
   137→
   138→  // Mac uses symbols without separator, Windows uses + separator
   139→  const keyParts = useMemo(() => {
   140→    if (onMac) {
   141→      // Mac format: symbols like ⌘⇧Z or single keys like S
   142→      // Split by known modifier symbols while keeping them
   143→      const parts: string[] = [];
   144→      let remaining = keys;
   145→      const modifiers = ['⌘', '⌥', '⇧', '⌃'];
   146→
   147→      for (const mod of modifiers) {
   148→        if (remaining.startsWith(mod)) {
   149→          parts.push(mod);
   150→          remaining = remaining.slice(mod.length);
   151→        }
   152→      }
   153→
   154→      if (remaining) {
   155→        parts.push(remaining);
   156→      }
   157→
   158→      return parts;
   159→    } else {
   160→      // Windows format: Ctrl+Shift+Z
   161→      return keys.split('+').map(k => k.trim());
   162→    }
   163→  }, [keys, onMac]);
   164→
   165→  return (
   166→    <span className="inline-flex items-center">
   167→      {keyParts.map((part, index) => (
   168→        <KeyBadge key={index} keyText={part} />
   169→      ))}
   170→    </span>
   171→  );
   172→}
